const packages = ["packages/gui-plugins/"]
const files = paths.filter(
  (file) => /\.(ts|tsx)$/.test(file) && !file.endsWith(".d.ts") && packages.some(prefix => file.startsWith(prefix)),
)
for (const chunk of [files]) {
  await $`bunx oxlint --format json ${chunk}`.nothrow().quiet().text()
}
